62	// 真实 app.py 进程
63	// ---------------------------------------------------------------------------
64	function startApp(label) {
65	  const proc = spawn("python3", [
66	    APP, "serve", "--host", "127.0.0.1", "--port", "0",
67	    "--data-dir", join(TMP, label),
68	  ], {cwd: HERE, stdio: ["ignore", "pipe", "pipe"]});
69	  const port = new Promise((resolve, reject) => {
70	    let buf = "";
71	    const onData = d => {
72	      buf += d.toString();
73	      const m = buf.match(/http:\/\/127\.0\.0\.1:(\d+)/);
74	      if (m) {
75	        proc.stdout.off("data", onData);
76	        resolve(Number(m[1]));
77	      }
78	    };
79	    proc.stdout.on("data", onData);
80	    proc.on("exit", code => reject(new Error(`app.py 意外退出（${code}）：${buf}`)));
81	  });
82	  return {proc, port};
83	}
