85	async function waitReady(base, deadlineMs = 8000) {
86	  const deadline = Date.now() + deadlineMs;
87	  while (Date.now() < deadline) {
88	    try {
89	      const res = await fetch(base + "/health");
90	      if (res.status === 200) return;
91	    } catch { /* 尚未就绪 */ }
92	    await new Promise(r => setTimeout(r, 100));
93	  }
94	  throw new Error("服务未在限定时间内就绪：" + base);
95	}
96	
97	async function stopApp(ctx) {
98	  ctx.proc.kill(); // SIGTERM：app.py 收到后走正常关闭
99	  const timer = setTimeout(() => {
100	    try { ctx.proc.kill("SIGKILL"); } catch { /* 已退出 */ }
101	  }, 2000);
102	  await new Promise(r => ctx.proc.on("exit", r));
103	  clearTimeout(timer);
104	}
