140	// 页面驱动：拦截导入请求与导入后的客户列表读取
141	// ---------------------------------------------------------------------------
142	async function openSession(browser, base, options = {}) {
143	  const page = await browser.newPage();
144	  const modes = {
145	    // ok 正常转发；close 连接断开；500 非成功状态；bad-json 无法解析；
146	    // no-clients 可解析但缺少客户数组
147	    list: "ok",
148	    // importOverride：null = 走真实后端；否则用给定 {status, body, contentType}
149	    importOverride: null,
150	    // importAbort 为 true 时直接断开导入请求（模拟网络错误）
151	    importAbort: false,
152	  };
153	  const counts = {importPosts: 0, listGets: 0};
154	
155	  // options.importReadFailStatus：让导入请求拿到该状态码，但回复体由一个
156	  // 在读取时即失败的 ReadableStream 承载——res.status 可读而 res.text()
157	  // 拒绝，模拟「连接在投递响应体过程中断开」。请求不离开页面，后端收不到。
158	  if (options.importReadFailStatus) {
159	    await page.evaluateOnNewDocument((status) => {
160	      const origFetch = window.fetch.bind(window);
161	      window.fetch = (input, init) => {
162	        const url = input && input.url ? input.url : String(input);
163	        if (url.includes("/api/clients/import")) {
164	          const stream = new ReadableStream({
165	            start(controller) {
166	              controller.error(new TypeError("unexpected end of stream"));
167	            },
168	          });
169	          return Promise.resolve(new Response(stream, {
170	            status,
171	            headers: {"Content-Type": "application/json; charset=utf-8"},
172	          }));
173	        }
174	        return origFetch(input, init);
175	      };
176	    }, options.importReadFailStatus);
177	  }
178	
179	  await page.setRequestInterception(true);
180	  page.on("request", request => {
181	    const url = request.url();
182	    if (request.method() === "GET" && url.endsWith("/api/clients")) {
183	      counts.listGets += 1;
184	      if (modes.list === "close") { request.abort("failed"); return; }
185	      if (modes.list === "500") {
186	        request.respond({status: 500, contentType: "application/json; charset=utf-8",
187	          body: JSON.stringify({error: "模拟的服务错误"})});
188	        return;
189	      }
190	      if (modes.list === "bad-json") {
191	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
192	          body: "<<<not valid json>>>"});
193	        return;
194	      }
195	      if (modes.list === "no-clients") {
196	        request.respond({status: 200, contentType: "application/json; charset=utf-8",
197	          body: JSON.stringify({unexpected: true})});
198	        return;
199	      }
200	      request.continue();
201	      return;
202	    }
203	    if (request.method() === "POST" && url.endsWith("/api/clients/import")) {
204	      counts.importPosts += 1;
205	      if (modes.importAbort) { request.abort("failed"); return; }
206	      if (modes.importOverride) {
207	        const {status, body, contentType} = modes.importOverride;
208	        request.respond({
209	          status,
210	          contentType: contentType || "application/json; charset=utf-8",
211	          body,
212	        });
213	        return;
214	      }
215	    }
216	    request.continue();
217	  });
218	
219	  await page.setCacheEnabled(false);
220	  await page.goto(base + "/", {waitUntil: "networkidle0"});
221	  return {page, modes, counts};
222	}
