225	async function importSnap(page) {
226	  return page.evaluate(() => {
227	    const text = sel => document.querySelector(sel)?.textContent.trim() ?? null;
228	    const report = document.getElementById("report");
229	    return {
230	      reportVisible: report.style.display === "block",
231	      banners: [...report.querySelectorAll(".banner")].map(b => ({
232	        cls: b.className,
233	        text: b.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
234	      })),
235	      reportText: report.innerText.replace(/[ \t\r\n]+/g, " ").trim(),
236	      failureItems: [...report.querySelectorAll(".failures li")]
237	        .map(li => li.innerText.replace(/[ \t\r\n]+/g, " ").trim()),
238	      failuresTitle: (() => {
239	        const p = report.querySelector(".failures p");
240	        return p ? p.innerText.replace(/[ \t\r\n]+/g, " ").trim() : null;
241	      })(),
242	      filename: text("#filename"),
243	      submitText: text("#submit-btn"),
244	      submitDisabled: document.getElementById("submit-btn").disabled,
245	      fileCount: document.getElementById("file-input").files.length,
246	      rows: [...document.querySelectorAll("#clients-body tr")].map(tr => ({
247	        id: tr.dataset.id,
248	        // td: 0 勾选框, 1 编号, 2 名称, 3 来源, 4 地区, 5 行业, 6 重要日期
249	        cells: [...tr.querySelectorAll("td")].slice(2).map(td => td.textContent.trim()),
250	      })),
251	      emptyOn: document.getElementById("clients-empty").classList.contains("on"),
252	      tableDisplay: getComputedStyle(document.getElementById("clients-table")).display,
253	      loadErrorOn: document.getElementById("clients-load-error").classList.contains("on"),
254	      loadErrorText: text("#clients-load-error"),
255	    };
256	  });
257	}
