302	  check(`${ctx}：不显示任何成功数量（不补造零新增/空明细）`,
303	    !/新增\s*\d+\s*条/.test(snap.reportText) &&
304	    !/未导入\s*\d+\s*条/.test(snap.reportText),
305	    snap.reportText);
306	  check(`${ctx}：不渲染未导入明细、页面没有 undefined/NaN/[object Object]`,
307	    snap.failureItems.length === 0 && !snap.failuresTitle &&
308	    !/undefined|NaN|\[object Object\]/.test(snap.reportText),
